/// The per-session token-usage ledger schema (gh-1241).
///
/// `usage.json` is the FOLDED artifact produced by [UsageChainFolder] over
/// a session's record chain: one record per sessionId forever (I1), with
/// `total == Σ(segments)` at every write (I2), per-segment/per-total
/// `source` markers (I3: `reported` | `estimated` | `mixed` — estimated
/// never silently substitutes reported), a per-model `byModel` split
/// inside each segment and the total (I5), and a `chain` fingerprint so a
/// corrupted or stale artifact is detected and rebuilt instead of merged
/// into (E3). The schema carries ONLY sessionId, model ids, ISO timestamps
/// and integer counts — no prompt text, no keys, no paths (I4; the
/// byte-scan in `usage_hygiene.dart` asserts it on every write).
///
/// All timestamps are derived from chain record timestamps, never from
/// wall clock — running the fold twice over the same chain yields
/// byte-identical output (I6), and clock skew across resume hosts cannot
/// reorder segments (E4: ordering is chain sequence, `at` is
/// informational).
library;

/// Provenance of a token count: the provider reported it inline, the fold
/// estimated it (chars/4 heuristic), or a mix of both kinds inside one
/// segment/total.
enum UsageSource {
  /// Every request in the scope carried provider-reported usage.
  reported,

  /// At least one request in the scope lacked provider usage and was
  /// priced by the estimator; none were reported.
  estimated,

  /// Both reported and estimated requests are present in the scope.
  mixed;

  /// The wire name written into usage.json.
  String get wire => name;

  /// Parses a wire name; tolerates unknown values by treating them as
  /// [UsageSource.estimated] — forward-compat: an older reader must not
  /// mislabel unseen future sources as provider-reported.
  factory UsageSource.parse(String? wire) => switch (wire) {
    'reported' => UsageSource.reported,
    'estimated' || null => UsageSource.estimated,
    _ => UsageSource.mixed,
  };
}

/// Integer token totals for one scope (a segment, one model's slice of a
/// scope, or the cumulative total).
final class UsageModelTotals {
  /// Creates [UsageModelTotals].
  const UsageModelTotals({
    this.requests = 0,
    this.input = 0,
    this.output = 0,
    this.cacheRead = 0,
    this.cacheWrite = 0,
    this.reasoning,
  });

  /// Every field zero.
  static const zero = UsageModelTotals();

  /// Number of provider requests folded into this scope.
  final int requests;

  /// Prompt (input) tokens.
  final int input;

  /// Completion (output) tokens.
  final int output;

  /// Input tokens served from a provider cache.
  final int cacheRead;

  /// Input tokens written into a provider cache.
  final int cacheWrite;

  /// Reasoning/thinking tokens, when at least one contributing provider
  /// reported them; `null` when no contributor did.
  final int? reasoning;

  /// Adds [other] into a new [UsageModelTotals].
  UsageModelTotals operator +(UsageModelTotals other) => UsageModelTotals(
    requests: requests + other.requests,
    input: input + other.input,
    output: output + other.output,
    cacheRead: cacheRead + other.cacheRead,
    cacheWrite: cacheWrite + other.cacheWrite,
    reasoning: reasoning != null
        ? (other.reasoning ?? 0) + reasoning!
        : other.reasoning,
  );

  /// The flat integer fields in schema order (shared by [UsageSegment] and
  /// [UsageLedgerTotal] serialization — one shape, two hosts).
  Map<String, dynamic> totalsJson() => {
    'requests': requests,
    'input': input,
    'output': output,
    'cacheRead': cacheRead,
    'cacheWrite': cacheWrite,
    if (reasoning != null) 'reasoning': reasoning,
  };

  /// Deserializes the flat integer fields from [json].
  factory UsageModelTotals.totalsFrom(Map<String, dynamic> json) =>
      UsageModelTotals(
        requests: json['requests'] as int? ?? 0,
        input: json['input'] as int? ?? 0,
        output: json['output'] as int? ?? 0,
        cacheRead: json['cacheRead'] as int? ?? 0,
        cacheWrite: json['cacheWrite'] as int? ?? 0,
        reasoning: json['reasoning'] as int?,
      );
}

/// Parses a `byModel` map from raw JSON; entries that are not
/// `string → object` pairs are skipped (tolerant reader).
Map<String, UsageModelTotals> usageByModelFromJson(Object? raw) => {
  if (raw is Map)
    for (final entry in raw.entries)
      if (entry.value is Map)
        entry.key as String: UsageModelTotals.totalsFrom(
          (entry.value as Map).cast<String, dynamic>(),
        ),
};

/// Merges [a] and [b] per model key (I5).
Map<String, UsageModelTotals> mergeUsageByModel(
  Map<String, UsageModelTotals> a,
  Map<String, UsageModelTotals> b,
) {
  final merged = Map<String, UsageModelTotals>.of(a);
  for (final entry in b.entries) {
    merged[entry.key] =
        (merged[entry.key] ?? UsageModelTotals.zero) + entry.value;
  }
  return Map.unmodifiable(merged);
}

/// One closed-or-open segment of a session's usage: the fold of every
/// provider request between two resume boundaries (gh-1241 I1/I2).
final class UsageSegment {
  /// Creates a [UsageSegment].
  const UsageSegment({
    required this.index,
    required this.totals,
    required this.byModel,
    required this.source,
    this.openedAt,
    this.closedAt,
  });

  /// 0-based position in the session's segment sequence (chain order — a
  /// resume APPENDS, never reorders, E4).
  final int index;

  /// Request/token sums over the segment.
  final UsageModelTotals totals;

  /// Per-model split of [totals] (I5); model ids are provider-controlled
  /// strings — schema-validated data, never shell-interpolated.
  final Map<String, UsageModelTotals> byModel;

  /// Provenance marker for this segment (I3).
  final UsageSource source;

  /// When the segment opened (the `usage_segment_start` marker's chain
  /// timestamp, or the first contributing record's). Informational only —
  /// ordering never derives from timestamps (E4).
  final DateTime? openedAt;

  /// When the segment last carried usage (the last contributing record's
  /// chain timestamp). `null` while the segment is open and empty.
  final DateTime? closedAt;

  /// Serializes to a JSON map (schema order fixed for byte-determinism).
  Map<String, dynamic> toJson() => {
    'index': index,
    if (openedAt != null) 'openedAt': openedAt!.toIso8601String(),
    if (closedAt != null) 'closedAt': closedAt!.toIso8601String(),
    ...totals.totalsJson(),
    'byModel': {
      for (final entry in byModel.entries) entry.key: entry.value.totalsJson(),
    },
    'source': source.wire,
  };

  /// Deserializes from a JSON map; unknown fields are ignored
  /// (forward-compat, UT-1).
  factory UsageSegment.fromJson(Map<String, dynamic> json) => UsageSegment(
    index: json['index'] as int? ?? 0,
    totals: UsageModelTotals.totalsFrom(json),
    byModel: usageByModelFromJson(json['byModel']),
    source: UsageSource.parse(json['source'] as String?),
    openedAt: DateTime.tryParse(json['openedAt'] as String? ?? ''),
    closedAt: DateTime.tryParse(json['closedAt'] as String? ?? ''),
  );
}

/// The cumulative view of a ledger: `total == Σ(segments)` at every write
/// (I2), with the per-model breakdown attached (I5) and a total-scope
/// provenance marker (I3).
final class UsageLedgerTotal {
  /// Creates a [UsageLedgerTotal].
  const UsageLedgerTotal({
    required this.totals,
    required this.byModel,
    required this.source,
  });

  /// Cumulative sums over every segment.
  final UsageModelTotals totals;

  /// Per-model cumulative split.
  final Map<String, UsageModelTotals> byModel;

  /// Provenance across the whole ledger (`mixed` when some segments are
  /// reported and others estimated).
  final UsageSource source;

  /// Serializes to a JSON map.
  Map<String, dynamic> toJson() => {
    ...totals.totalsJson(),
    'byModel': {
      for (final entry in byModel.entries) entry.key: entry.value.totalsJson(),
    },
    'source': source.wire,
  };

  /// Deserializes from a JSON map; unknown fields are ignored.
  factory UsageLedgerTotal.fromJson(Map<String, dynamic> json) =>
      UsageLedgerTotal(
        totals: UsageModelTotals.totalsFrom(json),
        byModel: usageByModelFromJson(json['byModel']),
        source: UsageSource.parse(json['source'] as String?),
      );
}

/// The top-level usage.json artifact: one record per sessionId, forever
/// (I1).
final class UsageLedger {
  /// Creates a [UsageLedger].
  const UsageLedger({
    required this.sessionId,
    required this.segments,
    required this.total,
    required this.chainRecords,
    required this.chainHash,
  });

  /// usage.json schema version written by this build.
  static const schemaVersion = 1;

  /// The session this ledger belongs to.
  final String sessionId;

  /// Number of `--continue`/`--resume` boundaries the session crossed:
  /// `segments.length - 1` (I1).
  int get resumedCount => segments.isEmpty ? 0 : segments.length - 1;

  /// Per-segment folds, chain order.
  final List<UsageSegment> segments;

  /// The cumulative view (I2).
  final UsageLedgerTotal total;

  /// Number of record lines on the session chain this fold consumed —
  /// mismatch with a fresh scan means the artifact is stale (E3).
  final int chainRecords;

  /// `sha256:`-prefixed fingerprint over every non-header chain line —
  /// hand-edits and crash remnants are detected, never merged into (E3).
  final String chainHash;

  /// Serializes to the artifact JSON map (schema order fixed for
  /// byte-determinism, I6).
  Map<String, dynamic> toJson() => {
    'version': schemaVersion,
    'sessionId': sessionId,
    'resumedCount': resumedCount,
    'segments': [for (final segment in segments) segment.toJson()],
    'total': total.toJson(),
    'chain': {'records': chainRecords, 'hash': chainHash},
  };

  /// Deserializes from a JSON map; unknown fields are ignored so newer
  /// writers never brick older readers (UT-1 forward-compat).
  factory UsageLedger.fromJson(Map<String, dynamic> json) {
    final rawSegments = json['segments'];
    final segments = <UsageSegment>[
      if (rawSegments is List)
        for (final segment in rawSegments)
          if (segment is Map)
            UsageSegment.fromJson(segment.cast<String, dynamic>()),
    ];
    final rawTotal = json['total'];
    final rawChain = json['chain'];
    return UsageLedger(
      sessionId: json['sessionId'] as String? ?? '',
      segments: segments,
      total: rawTotal is Map
          ? UsageLedgerTotal.fromJson(rawTotal.cast<String, dynamic>())
          : const UsageLedgerTotal(
              totals: UsageModelTotals.zero,
              byModel: {},
              source: UsageSource.estimated,
            ),
      chainRecords: rawChain is Map ? rawChain['records'] as int? ?? 0 : 0,
      chainHash: rawChain is Map ? rawChain['hash'] as String? ?? '' : '',
    );
  }
}

/// The chain half of the usage fold (gh-1241): walking a session's JSONL
/// record chain — the source of truth — into per-segment [FoldRequest]
/// lists, then into a [UsageLedger].
///
/// The scanner reads RAW lines, not typed records: it needs only a handful
/// of fields per record, and the chain's giant ledger-only payloads
/// (`model_request_summary`, blob tables) must not pay full
/// materialization. Known-irrelevant blob records (`trajectory_prompt_blob`
/// /`trajectory_manifest_blob`/`trajectory_wire_dump`) are skipped by
/// substring without `jsonDecode` — they can be megabytes of base64 and
/// contribute nothing to token sums.
///
/// Segment boundaries are `usage_segment_start` custom records appended by
/// the host at every session start/resume; a chain without any markers
/// folds as ONE segment (old sessions still produce a sane ledger).
/// Segment order is chain sequence (E4) — record timestamps land in the
/// artifact as informational `openedAt`/`closedAt` only.
library;

import 'dart:convert';
import 'dart:typed_data';

import 'package:crypto/crypto.dart';

import '../compaction/token_estimation.dart' show estimateTokens;
import '../context.dart' show messageFromJson;
import 'usage_fold.dart';
import 'usage_ledger.dart';

/// The custom record type that opens a usage segment (gh-1241 I1): appended
/// by the host at every session start/resume, consumed by
/// [UsageChainScanner] as the segment boundary.
const String usageSegmentStartCustomType = 'usage_segment_start';

/// The `model_request_summary` custom record type (trajectory ledger).
const String modelRequestSummaryCustomType = 'model_request_summary';

/// byModel key for requests whose model is unknown (errored requests that
/// never produced an assistant message, and their zero-filled fallbacks).
const String unknownUsageModel = 'unknown';

/// Chars-per-token of the shared chars/4 estimation heuristic
/// (`estimateTokens` in `token_estimation.dart`) — the fold's estimated
/// fallback prices input at the SAME rate the compaction estimator uses,
/// so an estimated request prices like the same request priced by the ctx
/// meter.
const int usageCharsPerToken = 4;

/// Custom-record types the scanner skips without decoding (megabyte-wide
/// ledger payloads irrelevant to token sums).
const _skipDecodeCustomTypes = [
  'trajectory_prompt_blob',
  'trajectory_manifest_blob',
  'trajectory_wire_dump',
];

/// One segment's raw fold input: the requests in chain order plus the
/// boundary timestamps derived from chain records.
final class UsageChainSegment {
  /// Creates a [UsageChainSegment].
  const UsageChainSegment({
    required this.requests,
    this.openedAt,
    this.closedAt,
  });

  /// The segment's provider requests.
  final List<FoldRequest> requests;

  /// First contributing record's chain timestamp (or the opening marker's).
  final DateTime? openedAt;

  /// Last contributing record's chain timestamp.
  final DateTime? closedAt;
}

/// The scan result: per-segment requests plus the chain fingerprint used
/// for stale/corrupt detection (E3) and idempotency (I6).
final class UsageChainScan {
  /// Creates a [UsageChainScan].
  const UsageChainScan({
    required this.segments,
    required this.recordCount,
    required this.chainHash,
  });

  /// Segments in chain order (always at least one).
  final List<UsageChainSegment> segments;

  /// Number of record lines consumed (header and torn lines excluded).
  final int recordCount;

  /// `sha256:`-prefixed fingerprint over the consumed raw record lines.
  final String chainHash;
}

/// Scans raw session-chain JSONL lines into [UsageChainScan].
final class UsageChainScanner {
  /// Creates a [UsageChainScanner].
  const UsageChainScanner();

  /// Scans [lines] (the session file's raw lines, header included).
  UsageChainScan scan(Iterable<String> lines) {
    final bytes = BytesBuilder(copy: false);
    var recordCount = 0;
    final segments = <_ScanSegment>[];
    _PendingSummary? pending;
    // The current segment, creating the first lazily so a chain with no
    // markers still folds as ONE segment.
    _ScanSegment current() {
      if (segments.isEmpty) segments.add(_ScanSegment());
      return segments.last;
    }

    void closeSegment(DateTime? boundaryAt) {
      if (pending case final summary?) {
        // A summary whose request never produced an assistant message
        // (provider error, abort): the request counts, with zero-fill
        // marked estimated — never silently dropped (E1's "counts summed
        // over what exists").
        segments.last.requests.add(summary.fallback());
        pending = null;
      }
      segments.add(_ScanSegment()..setOpenedAt(boundaryAt));
    }

    for (final raw in lines) {
      final line = raw.trimRight();
      if (line.isEmpty) continue;
      // Cheap pre-check for the giant blob records: hashed, counted, never
      // decoded.
      var skippedDecode = false;
      for (final blobType in _skipDecodeCustomTypes) {
        if (line.contains('"customType":"$blobType"')) {
          skippedDecode = true;
          break;
        }
      }
      final decoded = skippedDecode ? <String, dynamic>{} : _decode(line);
      if (decoded == null) continue; // torn line: contributes nothing
      final type = decoded['type'];
      if (type == 'session') continue; // header line
      recordCount += 1;
      bytes
        ..add(utf8.encode(line))
        ..add(const [10]);
      if (skippedDecode) continue;
      final timestamp = DateTime.tryParse(
        decoded['timestamp'] as String? ?? '',
      );
      if (type == 'custom') {
        final customType = decoded['customType'] as String? ?? '';
        if (customType == usageSegmentStartCustomType) {
          // A marker OPENS the segment it introduces: the first marker on
          // a chain claims the (lazy) first segment; a later marker closes
          // the previous segment only when it carried anything (an empty
          // trailing segment from a killed boot is not materialized, I1).
          // The marker itself is not a "contributing" record: the previous
          // segment's closedAt stays its last request's timestamp.
          if (!segments.lastOrNull.hasContentOrNull) {
            current().setOpenedAt(timestamp);
          } else {
            closeSegment(timestamp);
          }
          continue;
        }
      }
      final segment = current();
      segment.noteRecordAt(timestamp);
      if (type == 'custom') {
        final customType = decoded['customType'] as String? ?? '';
        if (customType == modelRequestSummaryCustomType) {
          pending = _PendingSummary.fromData(decoded['data']);
        }
        continue;
      }
      if (type != 'message') continue;
      final message = decoded['message'];
      if (message is! Map || message['role'] != 'assistant') continue;
      final request = _foldAssistant(message.cast<String, dynamic>(), pending);
      pending = null;
      current().requests.add(request);
    }
    // Close the trailing segment: a dangling summary still counts. A
    // header-only chain still yields ONE (empty) segment so the ledger
    // schema stays stable.
    if (pending case final summary?) {
      segments.lastOrNull?.requests.add(summary.fallback());
      pending = null;
    }
    if (segments.isEmpty) segments.add(_ScanSegment());
    return UsageChainScan(
      segments: [
        for (final segment in segments)
          UsageChainSegment(
            requests: segment.requests,
            openedAt: segment.openedAt ?? segment.firstRecordAt,
            closedAt: segment.closedAt,
          ),
      ],
      recordCount: recordCount,
      chainHash: 'sha256:${sha256.convert(bytes.toBytes())}',
    );
  }

  static Map<String, dynamic>? _decode(String line) {
    try {
      final decoded = jsonDecode(line);
      if (decoded is Map) return decoded.cast<String, dynamic>();
    } on Object {
      // Torn/foreign line: the tolerant reader skips it.
    }
    return null;
  }

  FoldRequest _foldAssistant(
    Map<String, dynamic> message,
    _PendingSummary? summary,
  ) {
    final model =
        (message['model'] as String?) ??
        (message['responseModel'] as String?) ??
        unknownUsageModel;
    final usage = message['usage'];
    final usageMap = usage is Map ? usage.cast<String, dynamic>() : null;
    final input = usageMap?['input'] as int? ?? 0;
    final output = usageMap?['output'] as int? ?? 0;
    final cacheRead = usageMap?['cacheRead'] as int? ?? 0;
    final cacheWrite = usageMap?['cacheWrite'] as int? ?? 0;
    final totalTokens = usageMap?['totalTokens'] as int? ?? 0;
    // Provider-reported iff any count is non-zero: AssistantMessage.usage
    // is non-nullable and providers that omit usage deserialize to
    // Usage.zero (AC4's fake-provider case).
    final reported =
        totalTokens > 0 ||
        input > 0 ||
        output > 0 ||
        cacheRead > 0 ||
        cacheWrite > 0;
    if (reported) {
      return FoldRequest(
        model: model,
        input: input,
        output: output,
        cacheRead: cacheRead,
        cacheWrite: cacheWrite,
        reasoning: usageMap?['reasoning'] as int?,
        source: UsageSource.reported,
      );
    }
    // Estimated fallback (I3): input priced from the paired request
    // summary's outbound chars, output from the assistant payload's
    // chars — both at the shared chars/4 rate. Estimation failures degrade
    // to zero, never a crash.
    final inputChars = summary?.inputChars ?? 0;
    return FoldRequest(
      model: model,
      input: (inputChars / usageCharsPerToken).ceil(),
      output: _estimateAssistantOutput(message),
      source: UsageSource.estimated,
    );
  }

  int _estimateAssistantOutput(Map<String, dynamic> message) {
    try {
      return estimateTokens(messageFromJson(message));
    } on Object {
      return 0;
    }
  }
}

/// Mutable scan state for one segment.
final class _ScanSegment {
  _ScanSegment();

  DateTime? openedAt;
  final List<FoldRequest> requests = [];
  DateTime? firstRecordAt;
  DateTime? closedAt;

  /// Whether anything contributed to this segment (a marker claiming an
  /// empty virgin segment does not count — killed boots leave nothing).
  bool get hasContent => requests.isNotEmpty || firstRecordAt != null;

  void setOpenedAt(DateTime? at) {
    openedAt ??= at;
  }

  void noteRecordAt(DateTime? at) {
    firstRecordAt ??= at;
    if (at != null) closedAt = at;
  }
}

/// Null-safe [ _ScanSegment.hasContent] probe for the boundary branch.
extension on _ScanSegment? {
  bool get hasContentOrNull => this?.hasContent ?? false;
}

/// A `model_request_summary` record waiting for the assistant message its
/// request produces (the summary always lands first on the chain).
final class _PendingSummary {
  _PendingSummary(this.inputChars);

  /// Σ `chars` of the summary's outbound request messages — the estimated
  /// input-token basis.
  final int inputChars;

  factory _PendingSummary.fromData(Object? data) {
    var chars = 0;
    if (data is Map) {
      final messages = data['messages'];
      if (messages is List) {
        for (final message in messages) {
          if (message is Map) {
            chars += message['chars'] as int? ?? 0;
          }
        }
      }
    }
    return _PendingSummary(chars);
  }

  /// The request never produced an assistant message: count it with
  /// zero-fill, marked estimated (E1).
  FoldRequest fallback() => const FoldRequest(
    model: unknownUsageModel,
    input: 0,
    output: 0,
    source: UsageSource.estimated,
  );
}

/// The rebuildable fold (gh-1241): records are the source of truth, so the
/// ledger is always recomputable from the chain — SIGKILL loses nothing
/// (AC3), running twice yields byte-identical output (I6).
final class UsageChainFolder {
  /// Creates a [UsageChainFolder].
  const UsageChainFolder({this.folder = const UsageFolder()});

  /// The pure fold math.
  final UsageFolder folder;

  /// Folds the session chain's raw [lines] into a [UsageLedger].
  UsageLedger foldChain({
    required String sessionId,
    required Iterable<String> lines,
    UsageChainScanner scanner = const UsageChainScanner(),
  }) {
    final scan = scanner.scan(lines);
    final segments = <UsageSegment>[
      for (var i = 0; i < scan.segments.length; i++)
        folder.foldSegment(
          i,
          scan.segments[i].requests,
          openedAt: scan.segments[i].openedAt,
          closedAt: scan.segments[i].closedAt,
        ),
    ];
    return UsageLedger(
      sessionId: sessionId,
      segments: segments,
      total: folder.totalOf(segments),
      chainRecords: scan.recordCount,
      chainHash: scan.chainHash,
    );
  }
}

