          requestSummaryLine(4),
          assistantLine(
            5,
            model: 'model-smol',
            usage: reportedUsage(input: 20, output: 10),
          ),
        ]);
        final segment = ledger.segments.single;
        expect(segment.totals.input, 120);
        expect(segment.totals.output, 60);
        expect(segment.byModel['model-main']!.input, 100);
