        segments: [sampleSegment()],
        total: const UsageLedgerTotal(
          totals: UsageModelTotals.zero,
          byModel: {},
          source: UsageSource.reported,
        ),
        chainRecords: 0,
        chainHash: '',
      );
      expect(fresh.resumedCount, 0);
    });
  });
}

