        final chain = [
          sessionHeaderLine('sess-1'),
          segmentMarkerLine(1),
          requestSummaryLine(2),
          assistantLine(3, usage: reportedUsage(input: 100, output: 50)),
          segmentMarkerLine(4),
          wireDumpLine(5), // giant blob: hashed, never decoded
          requestSummaryLine(6),
          assistantLine(7, usage: omittedUsage),
