      onWarning: (message) => io.writeln(tuiWarning(message)),
    );
    _webNetworkGate = _initWebNetworkGate(_cubeEnv);
    _cubeSource = config.cubeSource;
    _coreToolEnv = SessionVarsExecutionEnv(_cubeEnv, _sessionEnvVars);
