        // parameter: plugin output must route through the TUI transcript
        // (raw writes race the frame renderer and leave stray text on
        // screen).
        io: _PluginIO(this.io),
        config: _pluginConfig(plugin.name),
        pickOption: _pickOption,
        askLine: _askLine,
